/**
 * pathFilter.ts — Third-party / generated file filter.
 * Spec reference: Agents.md §5 F6
 *
 * Drop a file if its path matches any known third-party, generated,
 * vendored, built, or binary pattern.
 */

// ── Directory prefixes to exclude ────────────────────────────────────
const EXCLUDED_DIR_PREFIXES: string[] = [
  "node_modules/",
  "vendor/",
  "third_party/",
  ".yarn/",
  ".pnpm-store/",
  "bower_components/",
  "dist/",
  "build/",
  "out/",
  ".next/",
  "target/",
  "__pycache__/",
  ".venv/",
  "venv/",
  "coverage/",
];

// ── Exact filenames to exclude ───────────────────────────────────────
const EXCLUDED_FILENAMES: string[] = [
  "package-lock.json",
  "yarn.lock",
  "pnpm-lock.yaml",
  "poetry.lock",
  "Cargo.lock",
  "go.sum",
  "composer.lock",
];

// ── File extensions to exclude ───────────────────────────────────────
const EXCLUDED_EXTENSIONS: string[] = [
  ".min.js",
  ".min.css",
  ".map",
  ".lock",
  ".snap",
  ".svg",
  ".png",
  ".jpg",
  ".jpeg",
  ".gif",
  ".ico",
  ".pdf",
  ".woff",
  ".woff2",
  ".ttf",
  ".eot",
];

// ── Content markers for generated files ──────────────────────────────
const GENERATED_MARKERS: string[] = [
  "@generated",
  "DO NOT EDIT",
  "Code generated by",
];

/**
 * Check if a file path should be excluded based on path patterns.
 * Returns true if the file should be DROPPED.
 */
export function isExcludedPath(filePath: string): boolean {
  const normalized = filePath.replace(/\\/g, "/");
  const filename = normalized.split("/").pop() ?? "";

  // Check directory prefixes
  for (const prefix of EXCLUDED_DIR_PREFIXES) {
    if (
      normalized.startsWith(prefix) ||
      normalized.includes(`/${prefix}`)
    ) {
      return true;
    }
  }

  // Check exact filenames
  if (EXCLUDED_FILENAMES.includes(filename)) {
    return true;
  }

  // Check extensions (support compound extensions like .min.js)
  for (const ext of EXCLUDED_EXTENSIONS) {
    if (normalized.endsWith(ext)) {
      return true;
    }
  }

  return false;
}

/**
 * Check if file content indicates it is generated.
 * Only checks the first few lines for efficiency.
 * Returns true if the file should be DROPPED.
 */
export function isGeneratedContent(content: string): boolean {
  // Check first 5 lines or 500 chars, whichever is less
  const header = content.slice(0, 500);
  const firstLines = header.split("\n").slice(0, 5).join("\n");

  for (const marker of GENERATED_MARKERS) {
    if (firstLines.includes(marker)) {
      return true;
    }
  }

  return false;
}

/**
 * Filter an array of file paths, returning only those that pass the filter.
 */
export function filterPaths(paths: string[]): string[] {
  return paths.filter((p) => !isExcludedPath(p));
}
